package tv.moonga.classicworlds;

import java.awt.Rectangle;

/** Dimensions and column pagination from the pre-redesign login renderer. */
final class ClassicLayout {
  static final int WIDTH=765, HEIGHT=503, TILE_WIDTH=88, TILE_HEIGHT=19;
  final int columns, rows, gapX, gapY, startX, startY, maxPage;
  final int tileWidth;
  ClassicLayout(int count){this(count,true,23);}
  ClassicLayout(int count,boolean compact,int top) {
    int height=HEIGHT-top;
    tileWidth=compact?TILE_WIDTH:330;
    int cols=compact?WIDTH/(TILE_WIDTH+1)-1:2, rs=height/(TILE_HEIGHT+1);
    if(count>0) {
      int oldCols, oldRows;
      do {
        oldCols=cols;oldRows=rs;
        if(rs*(cols-1)>=count && cols>1)cols--;
        if(cols*(rs-1)>=count && rs>1)rs--;
        if(cols*(rs-1)>=count && rs>1)rs--;
      } while(cols!=oldCols||rs!=oldRows);
    }
    columns=cols;rows=rs;
    gapX=Math.min(5,(WIDTH-cols*tileWidth)/(cols+1));
    gapY=Math.min(5,(height-rs*TILE_HEIGHT)/(rs+1));
    startX=(WIDTH-cols*tileWidth-gapX*(cols-1))/2;
    startY=top+(height-rs*TILE_HEIGHT-gapY*(rs-1))/2;
    maxPage=Math.max(0,(count+rs-1)/rs-cols);
  }
  Rectangle tile(int visibleIndex) {
    return new Rectangle(startX+(visibleIndex/rows)*(tileWidth+gapX),startY+(visibleIndex%rows)*(TILE_HEIGHT+gapY),tileWidth,TILE_HEIGHT);
  }
  int first(int page) { return Math.max(0,Math.min(maxPage,page))*rows; }
}

package tv.moonga.classicworlds;

import java.awt.*;
import java.awt.event.*;
import java.awt.image.BufferedImage;
import javax.swing.*;
import java.util.EnumSet;
import net.runelite.api.WorldType;

/** Replaces the native login world button's entire hit area without a Swing button skin. */
final class ClassicWorldButton extends JComponent {
  // Preserve the classic 100:35 silhouette while covering the client's 120x50 control.
  static final int HEIGHT=50,WIDTH=(100*HEIGHT+34)/35;
  private final Runnable open;
  private final BufferedImage pixels=new BufferedImage(WIDTH,HEIGHT,BufferedImage.TYPE_INT_RGB);
  private BufferedImage background;
  private ClientBitmapFont smallFont,boldFont;
  private int world;
  private boolean pressed;
  private WorldPreferences options=WorldPreferences.DEFAULT;
  private BufferedImage[] flags;
  private int location=-1;
  private EnumSet<WorldType> types=EnumSet.noneOf(WorldType.class);
  private String activity="-";
  ClassicWorldButton(Runnable open){
    this.open=open;setOpaque(true);setFocusable(true);setDoubleBuffered(false);setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
    addMouseListener(new MouseAdapter(){
      @Override public void mousePressed(MouseEvent e){pressed=SwingUtilities.isLeftMouseButton(e);}
      @Override public void mouseReleased(MouseEvent e){boolean activate=pressed&&SwingUtilities.isLeftMouseButton(e)&&contains(e.getPoint());pressed=false;if(activate)open.run();}
      @Override public void mouseExited(MouseEvent e){pressed=false;}
    });
    for(String key:new String[]{"SPACE","ENTER"}){
      getInputMap(WHEN_FOCUSED).put(KeyStroke.getKeyStroke(key),"open");
    }
    getActionMap().put("open",new AbstractAction(){@Override public void actionPerformed(ActionEvent e){open.run();}});
  }
  void world(int id){if(world!=id){world=id;repaint();}}
  void background(BufferedImage image){background=image;repaint();}
  void fonts(ClientBitmapFont small,ClientBitmapFont bold){smallFont=small;boldFont=bold;repaint();}
  void flagSprites(BufferedImage[] images){flags=images;repaint();}
  void options(WorldPreferences value){options=value;repaint();}
  void worldInfo(int region,EnumSet<WorldType> worldTypes){
    worldInfo(region,worldTypes,"-");
  }
  void worldInfo(int region,EnumSet<WorldType> worldTypes,String worldActivity){
    EnumSet<WorldType> next=worldTypes==null?EnumSet.noneOf(WorldType.class):worldTypes;
    String nextActivity=worldActivity==null?"-":worldActivity;
    if(location!=region||!types.equals(next)||!activity.equals(nextActivity)){location=region;types=next.clone();activity=nextActivity;repaint();}
  }
  String subtitle(){
    if(options.buttonLine!=WorldPreferences.ButtonLine.GAME_MODE)return "Click to switch";
    WorldPreferences.GameMode mode=WorldPreferences.GameMode.of(types);
    return !activity.isBlank()&&!activity.equals("-")?activity:"Mode: "+mode;
  }
  private BufferedImage flag(){
    if(!options.showFlag||flags==null||location<0)return null;
    int index=location+(types.contains(WorldType.MEMBERS)?flags.length/2:0);
    return index<flags.length?flags[index]:null;
  }
  @Override public Dimension getPreferredSize(){return new Dimension(WIDTH,HEIGHT);}
  @Override protected void paintComponent(Graphics graphics){
    Graphics2D g=PixelDrawing.raster(pixels);
    try{
      g.setPaint(new GradientPaint(0,0,new Color(0x494b54),0,HEIGHT,new Color(0x202127)));g.fillRect(0,0,WIDTH,HEIGHT);
      if(background!=null)g.drawImage(background,0,0,WIDTH,HEIGHT,null);
      else{g.setColor(new Color(0x77766e));g.drawRect(1,1,WIDTH-3,HEIGHT-3);g.setColor(Color.BLACK);g.drawRect(0,0,WIDTH-1,HEIGHT-1);}
    }finally{g.dispose();}
    PixelDrawing.blit(graphics,pixels,0,0,getWidth(),getHeight());
    if(boldFont!=null&&smallFont!=null){
      String title="World "+world,subtitle=fit(subtitle(),WIDTH-12);BufferedImage flag=flag();
      int titleWidth=boldFont.width(title)+(flag==null?0:flag.getWidth()+4);
      int width=Math.max(titleWidth,smallFont.width(subtitle))+4;
      BufferedImage text=new BufferedImage(width,36,BufferedImage.TYPE_INT_ARGB);
      Graphics2D label=PixelDrawing.raster(text);
      try{
        int x=(width-titleWidth)/2;boldFont.draw(label,title,x,16,0xffffff,0);
        if(flag!=null)label.drawImage(flag,x+boldFont.width(title)+4,2,null);
        smallFont.center(label,subtitle,width/2,30,0xffffff,0);
      }finally{label.dispose();}
      new PixelDrawing.DeviceGrid(graphics).centered(graphics,text,getWidth()/2,getHeight()/2);
    }
  }
  private String fit(String text,int width){
    if(smallFont.width(text)<=width)return text;
    while(!text.isEmpty()&&smallFont.width(text+"...")>width)text=text.substring(0,text.length()-1);
    return text+"...";
  }
}

package tv.moonga.classicworlds;

import java.awt.*;
import java.awt.event.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.BiConsumer;
import javax.swing.*;

/** A single opaque surface stays above the game canvas and other login overlays. */
final class ClassicWorldPanel extends JPanel {
  private final Consumer<WorldEntry> select;
  private final Runnable close;
  private List<WorldEntry> worlds=Collections.emptyList();
  private List<WorldEntry> allWorlds=Collections.emptyList();
  private WorldPreferences options=WorldPreferences.DEFAULT;
  private BiConsumer<String,Object> settingsChanged=(key,value)->{};
  private final WorldMenus menus=new WorldMenus(this::preferenceChanged);
  private BufferedImage[] backgrounds,flags,stars,arrows;
  private BufferedImage leftArrow,rightArrow;
  private ClientBitmapFont smallFont,boldFont;
  private DisplaySize displaySize=DisplaySize.NORMAL;
  private final BufferedImage pixels=new BufferedImage(765,503,BufferedImage.TYPE_INT_RGB);
  private int page,sort,hover=-1;
  private boolean ascending=true, busy;
  private Point mouse=new Point(-1,-1);
  private String message="Loading worlds...";
  private static final int[] HEADINGS={280,390,500,610};

  ClassicWorldPanel(Consumer<WorldEntry> select,Runnable close) {
    this.select=select;this.close=close;setOpaque(true);setBackground(Color.BLACK);setFocusable(true);setDoubleBuffered(false);
    MouseAdapter input=new MouseAdapter(){
      private int pressed=-1;
      @Override public void mouseMoved(MouseEvent e){mouse=logical(e.getPoint());menus.mouse(mouse);hover=hit(mouse);repaint();}
      @Override public void mouseExited(MouseEvent e){hover=-1;mouse=new Point(-1,-1);menus.mouse(mouse);repaint();}
      @Override public void mousePressed(MouseEvent e){if(SwingUtilities.isLeftMouseButton(e))pressed=hit(logical(e.getPoint()));}
      @Override public void mouseReleased(MouseEvent e){
        if(!SwingUtilities.isLeftMouseButton(e))return;
        int target=hit(logical(e.getPoint()));
        if(target==pressed)activate(target);
        pressed=-1;
      }
      @Override public void mouseWheelMoved(MouseWheelEvent e){if(menus.isOpen())menus.step(Integer.signum(e.getWheelRotation()));else turn(Integer.signum(e.getWheelRotation()));repaint();e.consume();}
    };
    addMouseListener(input);addMouseMotionListener(input);addMouseWheelListener(input);
    bind("ESCAPE",()->handleKey(KeyEvent.VK_ESCAPE));bind("LEFT",()->handleKey(KeyEvent.VK_LEFT));bind("RIGHT",()->handleKey(KeyEvent.VK_RIGHT));
    bind("UP",()->handleKey(KeyEvent.VK_UP));bind("DOWN",()->handleKey(KeyEvent.VK_DOWN));bind("ENTER",()->handleKey(KeyEvent.VK_ENTER));
  }
  void handleKey(int key){
    switch(key){
      case KeyEvent.VK_ESCAPE:if(!menus.dismiss())close.run();break;
      case KeyEvent.VK_LEFT:if(!menus.isOpen())turn(-1);break;
      case KeyEvent.VK_RIGHT:if(!menus.isOpen())turn(1);break;
      case KeyEvent.VK_UP:menus.step(-1);break;
      case KeyEvent.VK_DOWN:menus.step(1);break;
      case KeyEvent.VK_ENTER:menus.choose();break;
      default:return;
    }
    repaint();
  }
  private void bind(String key,Runnable callback){
    getInputMap(WHEN_IN_FOCUSED_WINDOW).put(KeyStroke.getKeyStroke(key),key);
    getActionMap().put(key,new AbstractAction(){
      @Override public boolean isEnabled(){return isVisible();}
      @Override public void actionPerformed(ActionEvent e){callback.run();}
    });
  }
  void assets(BufferedImage[] backgrounds,BufferedImage[] flags,BufferedImage[] stars,BufferedImage[] arrows){
    this.backgrounds=backgrounds;this.flags=flags;this.stars=stars;this.arrows=arrows;repaint();
  }
  void pageArrows(BufferedImage left,BufferedImage right){leftArrow=left;rightArrow=right;repaint();}
  void fonts(ClientBitmapFont small,ClientBitmapFont bold){smallFont=small;boldFont=bold;repaint();}
  void displaySize(DisplaySize size){displaySize=size==null?DisplaySize.NORMAL:size;menus.settings(options,displaySize);repaint();}
  void preferencesChanged(BiConsumer<String,Object> callback){settingsChanged=callback;}
  void options(WorldPreferences value){
    boolean reorder=value.mode!=options.mode||value.region!=options.region||value.membership!=options.membership||value.compact!=options.compact;
    options=value;menus.settings(options,displaySize);if(reorder){page=0;sortWorlds();}repaint();
  }
  private void preferenceChanged(String key,Object value){
    if(key.equals("displaySize"))displaySize((DisplaySize)value);else options(options.with(key,value));
    settingsChanged.accept(key,value);hover=-1;repaint();
  }
  void worlds(List<WorldEntry> values){allWorlds=new ArrayList<>(values);sortWorlds();hover=hit(mouse);message=allWorlds.isEmpty()?"Loading worlds...":worlds.isEmpty()?"No worlds match this membership filter.":"";repaint();}
  ClassicLayout worldLayout(){return new ClassicLayout(worlds.size(),options.compact,57);}
  void status(String text){message=text;repaint();}
  void busy(boolean value){busy=value;repaint();}
  private void sortWorlds(){
    Comparator<WorldEntry> comparator;
    switch(sort){
      case 1: comparator=Comparator.comparingInt(w->w.players<0?2001:w.players);break;
      case 2: comparator=Comparator.comparingInt(w->w.location);break;
      case 3: comparator=options.compact?Comparator.comparing(WorldEntry::members).thenComparing(WorldEntry::typeLabel):Comparator.comparing(w->w.activity);break;
      default: comparator=Comparator.comparingInt(w->w.id);
    }
    if(!ascending)comparator=comparator.reversed();
    worlds=options.order(allWorlds,comparator.thenComparingInt(w->w.id));
    message=allWorlds.isEmpty()?"Loading worlds...":worlds.isEmpty()?"No worlds match this membership filter.":"";
    page=Math.min(page,worldLayout().maxPage);hover=-1;
  }
  private void turn(int direction){page=Math.max(0,Math.min(worldLayout().maxPage,page+direction));hover=-1;repaint();}
  private double scale(){return Math.min(1,Math.min(getWidth()/765.0,getHeight()/503.0));}
  private int originX(){return (getWidth()-(int)(765*scale()))/2;}
  Point logical(Point point){double s=scale();return new Point((int)((point.x-originX())/s),(int)(point.y/s));}
  int hit(Point p){
    Integer menu=menus.hit(p);if(menu!=null)return menu;
    if(new Rectangle(708,4,50,16).contains(p))return -2;
    for(int i=0;i<HEADINGS.length;i++){
      if(new Rectangle(HEADINGS[i],0,15,23).contains(p))return -10-i*2;
      if(new Rectangle(HEADINGS[i]+15,0,95,23).contains(p))return -11-i*2;
    }
    ClassicLayout layout=worldLayout();
    if(page>0&&pageArrowBounds(true).contains(p))return -3;
    if(page<layout.maxPage&&pageArrowBounds(false).contains(p))return -4;
    int first=layout.first(page);
    for(int i=0;i<layout.columns*layout.rows&&first+i<worlds.size();i++)
      if(layout.tile(i).contains(p))return first+i;
    return -1;
  }
  void activate(int target){
    if(target==-2){close.run();return;}
    if(busy)return;
    if(menus.activate(target)){hover=-1;repaint();return;}
    if(target==-3){turn(-1);return;}if(target==-4){turn(1);return;}
    if(target<=-10&&target>=-17){int action=-target-10;sort=action/2;ascending=action%2==0;page=0;sortWorlds();repaint();return;}
    if(target>=0&&target<worlds.size()&&worlds.get(target).selectable())select.accept(worlds.get(target));
  }
  @Override protected void paintComponent(Graphics graphics){
    super.paintComponent(graphics);
    Graphics2D g=PixelDrawing.raster(pixels);
    try{
      g.setColor(Color.BLACK);g.fillRect(0,0,765,503);
      g.setPaint(new GradientPaint(0,0,new Color(12425273),0,23,new Color(9135624)));g.fillRect(0,0,125,23);
      g.setPaint(new GradientPaint(0,0,new Color(0x4f4f4f),0,23,new Color(0x292929)));g.fillRect(125,0,640,23);
      center(g,boldFont,"Select a world",62,15,Color.BLACK);
      sprite(g,stars,1,140,1);sprite(g,stars,0,140,12);
      text(g,smallFont,"Members only world",152,10,Color.WHITE);text(g,smallFont,"Free world",152,21,Color.WHITE);
      String[] labels={"World","Players","Location",options.compact?"Type":"Activity"};
      for(int i=0;i<labels.length;i++){
        arrow(g,HEADINGS[i],4,true,sort==i&&ascending);
        arrow(g,HEADINGS[i]+15,4,false,sort==i&&!ascending);
        text(g,boldFont,labels[i],HEADINGS[i]+32,17,Color.WHITE);
      }
      g.setColor(Color.BLACK);g.fillRect(708,4,50,16);center(g,smallFont,"Cancel",733,16,Color.WHITE);
      ClassicLayout layout=worldLayout();int first=layout.first(page);
      for(int i=0;i<layout.columns*layout.rows&&first+i<worlds.size();i++){
        WorldEntry w=worlds.get(first+i);Rectangle r=layout.tile(i);
        boolean nativeBackground=sprite(g,backgrounds,w.background(),r.x,r.y);
        if(!nativeBackground){
          Color top=w.members()?new Color(0xb8a670):new Color(0xa6a6a6);
          g.setPaint(new GradientPaint(0,r.y,top,0,r.y+19,new Color(0x545454)));g.fillRect(r.x,r.y,88,19);
        }
        if(hover==first+i&&w.selectable()&&!busy){g.setColor(new Color(255,255,255,128));g.fillRect(r.x,r.y,88,19);}
        // The original renderer used half the flag sheet, not a fixed eight-region offset.
        sprite(g,flags,w.location+(w.members()&&flags!=null?flags.length/2:0),r.x+29,r.y);
        center(g,boldFont,Integer.toString(w.id),r.x+15,r.y+14,w.types.contains(net.runelite.api.WorldType.DEADMAN)?Color.RED:Color.BLACK);
        center(g,smallFont,w.population(),r.x+60,r.y+14,Color.WHITE);
        if(!options.compact){
          if(hover==first+i){g.setColor(new Color(192,169,70,65));g.fillRect(r.x+90,r.y,r.width-90,19);}
          Shape clip=g.getClip();g.clipRect(r.x+93,r.y,r.width-95,r.height);
          text(g,smallFont,w.activity.equals("-")?WorldPreferences.GameMode.of(w.types).toString():w.activity,r.x+94,r.y+14,Color.WHITE);g.setClip(clip);
        }
      }
      if(worlds.isEmpty()||!message.isEmpty())center(g,boldFont,message,382,worlds.isEmpty()?253:498,Color.YELLOW);
      menus.paint(g,smallFont);
    }finally{g.dispose();}
    PixelDrawing.blit(graphics,pixels,originX(),0,(int)(765*scale()),(int)(503*scale()));
    ClassicLayout layout=worldLayout();
    if(page>0)paintPageArrow(graphics,true);
    if(page<layout.maxPage)paintPageArrow(graphics,false);
    paintTooltip(graphics);
  }
  private void paintTooltip(Graphics graphics){
    if(!options.compact||menus.isOpen()||hover<0||hover>=worlds.size()||mouse.y<57||smallFont==null)return;
    PixelDrawing.DeviceGrid grid=new PixelDrawing.DeviceGrid(graphics,displaySize);
    Point topLeft=grid.point(0,0),bottomRight=grid.point(getWidth(),getHeight());
    int available=Math.max(8,(int)((bottomRight.x-topLeft.x)/grid.scale)-4);
    String text=worlds.get(hover).tooltip();int width=Math.min(available,smallFont.width(text)+6);
    int height=smallFont.ascent+8;
    BufferedImage tooltip=new BufferedImage(width,height,BufferedImage.TYPE_INT_RGB);Graphics2D g=PixelDrawing.raster(tooltip);
    try{
      g.setColor(new Color(0xffffa0));g.fillRect(0,0,width,height);g.setColor(Color.BLACK);g.drawRect(0,0,width-1,height-1);
      g.clipRect(2,1,width-4,height-2);smallFont.center(g,text,width/2,smallFont.ascent+4,0,-1);
    }finally{g.dispose();}
    Point cursor=grid.point(originX()+mouse.x*scale(),mouse.y*scale());
    int deviceWidth=(int)Math.round(width*grid.scale),deviceHeight=(int)Math.round(height*grid.scale);
    int x=Math.max(topLeft.x,Math.min(bottomRight.x-deviceWidth,cursor.x-deviceWidth/2));
    int y=cursor.y+(int)Math.round(25*grid.scale);
    if(y+deviceHeight>bottomRight.y)y=cursor.y-(int)Math.round(25*grid.scale)-deviceHeight;
    grid.draw(graphics,tooltip,x,Math.max(topLeft.y,y));
  }
  private void arrow(Graphics2D g,int x,int y,boolean up,boolean selected){
    if(sprite(g,arrows,up?(selected?2:0):(selected?3:1),x,y))return;
    g.setColor(selected?Color.YELLOW:Color.GRAY);
    g.fillPolygon(new int[]{x,x+7,x+14},up?new int[]{y+13,y,y+13}:new int[]{y,y+13,y},3);
  }
  Rectangle pageArrowBounds(boolean left){
    Rectangle r=pageArrowComponentBounds(left);Point p=logical(r.getLocation());
    return new Rectangle(p.x,p.y,(int)(r.width/scale()),(int)(r.height/scale()));
  }
  private Rectangle pageArrowComponentBounds(boolean left){
    BufferedImage sprite=left?leftArrow:rightArrow;
    int width=(int)((sprite==null?45:sprite.getWidth())*scale()),height=(int)((sprite==null?37:sprite.getHeight())*scale());
    return new Rectangle(left?8:getWidth()-width-8,getHeight()/2-height/2,width,height);
  }
  private void paintPageArrow(Graphics graphics,boolean left){
    BufferedImage sprite=left?leftArrow:rightArrow;
    if(sprite!=null){Rectangle r=pageArrowComponentBounds(left);PixelDrawing.blit(graphics,sprite,r.x,r.y,r.width,r.height);}
  }
  private static boolean sprite(Graphics2D g,BufferedImage[] sprites,int i,int x,int y){
    if(sprites==null||i<0||i>=sprites.length||sprites[i]==null)return false;
    g.drawImage(sprites[i],x,y,null);return true;
  }
  private static void center(Graphics2D g,ClientBitmapFont font,String text,int x,int y,Color color){if(font!=null)font.center(g,text,x,y,color.getRGB(),-1);}
  private static void text(Graphics2D g,ClientBitmapFont font,String text,int x,int y,Color color){if(font!=null)font.draw(g,text,x,y,color.getRGB(),-1);}
}

package tv.moonga.classicworlds;

import net.runelite.client.config.*;

@ConfigGroup(ClassicWorldSelectorConfig.GROUP)
public interface ClassicWorldSelectorConfig extends Config {
  String GROUP="moongaClassicWorldSelector";
  @ConfigItem(keyName="displaySize",name="World hover text size",
      description="Only the compact world tooltip: Normal 100%, Larger 115%, Extra Large 130%. The login button stays the same size.",position=0)
  default DisplaySize displaySize(){return DisplaySize.NORMAL;}
  @ConfigItem(keyName="showFlag",name="Login button country flag",description="Show the current world's country flag beside World ###",position=1)
  default boolean showFlag(){return true;}
  @ConfigItem(keyName="buttonLine",name="World info on login button",description="On shows the current game mode or activity. Off shows Click to switch.",position=2)
  default WorldPreferences.ButtonLine buttonLine(){return WorldPreferences.ButtonLine.CLICK_TO_SWITCH;}
  @ConfigItem(keyName="preferredMode",name="Game mode first",description="Place this game mode first without hiding other worlds",position=3)
  default WorldPreferences.GameMode preferredMode(){return WorldPreferences.GameMode.ALL;}
  @ConfigItem(keyName="preferredRegion",name="Region first",description="Place this region first within each game-mode group",position=4)
  default WorldPreferences.Region preferredRegion(){return WorldPreferences.Region.ALL;}
  @ConfigItem(keyName="membership",name="Membership",description="Show all, show only members/F2P, or place members/F2P first within preference groups",position=5)
  default WorldPreferences.Membership membership(){return WorldPreferences.Membership.ALL;}
  @ConfigItem(keyName="compact",name="Compact view",description="Use the classic grid; turn off to show the activity beside each world",position=6)
  default boolean compact(){return true;}
}

package tv.moonga.classicworlds;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.*;
import net.runelite.api.*;
import net.runelite.api.events.ClientTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.WorldService;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.WorldUtil;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import com.google.inject.Provides;
import java.awt.event.KeyEvent;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.KeyListener;

@PluginDescriptor(name="Classic World Selector",description="Restore the compact classic login world grid",tags={"world","login","classic","region"})
public class ClassicWorldSelectorPlugin extends Plugin {
  @Inject private Client client;
  @Inject private ClientThread clientThread;
  @Inject private WorldService worldService;
  @Inject private ScheduledExecutorService executor;
  @Inject private ClassicWorldSelectorConfig config;
  @Inject private ConfigManager configManager;
  @Inject private KeyManager keyManager;
  private ClassicWorldPanel panel;
  private ClassicWorldButton button;
  private JLayeredPane layer;
  private javax.swing.Timer timer;
  private volatile boolean running,opened;
  private volatile List<WorldEntry> serviceWorlds=Collections.emptyList();
  private final java.util.concurrent.atomic.AtomicBoolean refreshing=new java.util.concurrent.atomic.AtomicBoolean();
  private boolean assetsLoaded;
  private int ticks;
  private volatile Map<Integer,WorldEntry> knownWorlds=Collections.emptyMap();
  private WorldPreferences currentPreferences=WorldPreferences.DEFAULT;
  private final KeyListener selectorKeys=new KeyListener(){
    @Override public boolean isEnabledOnLoginScreen(){return true;}
    @Override public void keyPressed(KeyEvent event){
      if(!selectorInputActive())return;
      event.consume();
      int key=event.getKeyCode();
      SwingUtilities.invokeLater(()->{if(selectorInputActive()&&panel!=null)panel.handleKey(key);});
    }
    @Override public void keyReleased(KeyEvent event){if(selectorInputActive())event.consume();}
    @Override public void keyTyped(KeyEvent event){if(selectorInputActive())event.consume();}
  };
  private boolean selectorInputActive(){return running&&opened&&canSelect(client.getGameState());}

  @Override protected void startUp(){
    running=true;
    keyManager.registerKeyListener(selectorKeys);
    SwingUtilities.invokeLater(()->{
      if(!running)return;
      panel=new ClassicWorldPanel(this::select,this::close);
      button=new ClassicWorldButton(this::open);button.world(client.getWorld());
      panel.preferencesChanged(this::savePreference);
      applyDisplaySize();
      panel.setVisible(false);timer=new javax.swing.Timer(100,e->position());timer.start();position();
      clientThread.invokeLater(()->{if(running)sample();});
    });
    refreshWorlds();
  }
  static boolean canSelect(GameState state){return state==GameState.LOGIN_SCREEN;}
  @Provides ClassicWorldSelectorConfig provideConfig(ConfigManager manager){return manager.getConfig(ClassicWorldSelectorConfig.class);}
  @Subscribe public void onConfigChanged(ConfigChanged event){
    if(ClassicWorldSelectorConfig.GROUP.equals(event.getGroup()))SwingUtilities.invokeLater(()->{if(running&&panel!=null){applyDisplaySize();position();}});
  }
  private void applyDisplaySize(){
    DisplaySize size=config==null?DisplaySize.NORMAL:config.displaySize();
    panel.displaySize(size);
    currentPreferences=WorldPreferences.from(config);panel.options(currentPreferences);button.options(currentPreferences);
  }
  private void savePreference(String key,Object value){
    // Apply to the visible button immediately, independently of ConfigChanged dispatch timing.
    if(!key.equals("displaySize")){currentPreferences=currentPreferences.with(key,value);button.options(currentPreferences);}
    configManager.setConfiguration(ClassicWorldSelectorConfig.GROUP,key,value);
  }
  @Subscribe public void onClientTick(ClientTick event){if(running&&++ticks%50==0&&canSelect(client.getGameState()))sample();}
  private void sample(){
    if(!running)return;
    List<WorldEntry> snapshot=new ArrayList<>();
    net.runelite.api.World[] nativeWorlds=client.getWorldList();
    if(nativeWorlds!=null&&nativeWorlds.length>0){for(net.runelite.api.World w:nativeWorlds)if(w!=null)snapshot.add(WorldEntry.from(w));}
    else snapshot.addAll(serviceWorlds);
    EnumComposition locations=canSelect(client.getGameState())?client.getEnum(EnumID.WORLD_LOCATIONS):null;
    for(int i=0;i<snapshot.size();i++){
      WorldEntry world=snapshot.get(i);
      if(locations!=null)snapshot.set(i,world.withServerLocation(locations.getIntValue(world.id)));
    }
    if(!assetsLoaded&&client.getIndexSprites()!=null){
      BufferedImage[] bg=images(814),flags=images(815),stars=images(817),arrows=images(816);
      BufferedImage[] left=images(308),right=images(309),worldButton=images(818);
      ClientBitmapFont small=font(494),bold=font(496);
      assetsLoaded=bg!=null&&flags!=null&&stars!=null&&arrows!=null&&first(left)!=null&&first(right)!=null&&first(worldButton)!=null&&small!=null&&bold!=null;
      SwingUtilities.invokeLater(()->{if(running&&panel!=null){panel.assets(bg,flags,stars,arrows);panel.pageArrows(first(left),first(right));panel.fonts(small,bold);button.background(first(worldButton));button.fonts(small,bold);button.flagSprites(flags);}});
    }
    Map<Integer,WorldEntry> worldMap=new HashMap<>();for(WorldEntry world:snapshot)worldMap.put(world.id,world);knownWorlds=Collections.unmodifiableMap(worldMap);
    SwingUtilities.invokeLater(()->{if(running&&panel!=null)panel.worlds(snapshot);});
  }
  private static BufferedImage first(BufferedImage[] images){return images==null||images.length==0?null:images[0];}
  private ClientBitmapFont font(int archive){
    IndexDataBase metrics=client.getIndex(13);if(metrics==null)return null;
    byte[] data=metrics.loadData(archive,0);if(data==null)return null;
    return ClientBitmapFont.from(data,client.getSprites(client.getIndexSprites(),archive,0));
  }
  private void refreshWorlds(){
    if(!refreshing.compareAndSet(false,true))return;
    executor.execute(()->{
      try{
        if(!running)return;
        // WorldService can wait for its first HTTP result. Never call it on the game thread.
        worldService.refresh();
        net.runelite.http.api.worlds.WorldResult result=worldService.getWorlds();
        List<WorldEntry> values=new ArrayList<>();
        if(result!=null&&result.getWorlds()!=null)for(net.runelite.http.api.worlds.World w:result.getWorlds())
          values.add(new WorldEntry(w.getId(),w.getPlayers(),w.getRegion()==null?0:w.getRegion().getId(),w.getActivity(),w.getAddress(),WorldUtil.toWorldTypes(w.getTypes())));
        if(running){serviceWorlds=Collections.unmodifiableList(values);clientThread.invokeLater(()->{if(running)sample();});}
      }catch(RuntimeException error){
        org.slf4j.LoggerFactory.getLogger(getClass()).warn("Could not refresh the classic world list",error);
        SwingUtilities.invokeLater(()->{if(running&&panel!=null)panel.status("World list unavailable. Close and reopen to retry.");});
      }finally{refreshing.set(false);}
    });
  }
  private BufferedImage[] images(int archive){
    try{
      SpritePixels[] sprites=client.getSprites(client.getIndexSprites(),archive,0);
      if(sprites==null)return null;
      BufferedImage[] images=new BufferedImage[sprites.length];
      for(int i=0;i<sprites.length;i++)if(sprites[i]!=null){
        SpritePixels sprite=sprites[i];
        // Native drawAt includes the transparent canvas and sprite offsets.
        BufferedImage image=new BufferedImage(Math.max(sprite.getMaxWidth(),sprite.getWidth()+sprite.getOffsetX()),Math.max(sprite.getMaxHeight(),sprite.getHeight()+sprite.getOffsetY()),BufferedImage.TYPE_INT_ARGB);
        Graphics2D g=image.createGraphics();try{g.drawImage(sprite.toBufferedImage(),sprite.getOffsetX(),sprite.getOffsetY(),null);}finally{g.dispose();}
        images[i]=image;
      }
      return images;
    }catch(RuntimeException e){return null;}
  }
  private void open(){
    if(!running||!canSelect(client.getGameState()))return;
    opened=true;position();clientThread.invokeLater(()->{if(running)sample();});refreshWorlds();
  }
  private void close(){opened=false;if(panel!=null)panel.busy(false);position();}
  private void position(){
    if(panel==null||button==null)return;
    Canvas canvas=client.getCanvas();JRootPane root=SwingUtilities.getRootPane(canvas);
    if(root==null){panel.setVisible(false);button.setVisible(false);return;}
    if(layer!=root.getLayeredPane()){
      if(layer!=null){layer.remove(panel);layer.remove(button);}
      layer=root.getLayeredPane();layer.add(button,JLayeredPane.PALETTE_LAYER);layer.add(panel,JLayeredPane.POPUP_LAYER);
    }
    java.awt.Point origin=SwingUtilities.convertPoint(canvas,0,0,layer);
    boolean login=running&&canSelect(client.getGameState());if(!login)opened=false;
    panel.setBounds(origin.x,origin.y,canvas.getWidth(),canvas.getHeight());panel.setVisible(login&&opened);
    Dimension size=button.getPreferredSize();
    button.setBounds(origin.x+Math.max(0,(canvas.getWidth()-765)/2)+5,origin.y+498-size.height,size.width,size.height);
    button.world(client.getWorld());button.setVisible(login&&!opened);
    WorldEntry current=knownWorlds.get(client.getWorld());
    button.worldInfo(current==null?-1:current.location,current==null?client.getWorldType():current.types,current==null?"-":current.activity);
  }
  private void select(WorldEntry entry){
    if(!entry.selectable())return;panel.busy(true);
    clientThread.invokeLater(()->{
      if(!running)return;
      if(!canSelect(client.getGameState())){SwingUtilities.invokeLater(()->{if(running)close();});return;}
      try{
        net.runelite.api.World world=client.createWorld();
        world.setId(entry.id);world.setAddress(entry.address);world.setActivity(entry.activity);
        world.setLocation(entry.location);world.setPlayerCount(entry.players);world.setTypes(entry.types.clone());
        client.changeWorld(world);
        SwingUtilities.invokeLater(()->{if(running)close();});
      }catch(RuntimeException error){SwingUtilities.invokeLater(()->{if(running){panel.busy(false);panel.status("Could not select this world. Please try again.");}});}
    });
  }
  @Override protected void shutDown(){
    running=false;opened=false;
    keyManager.unregisterKeyListener(selectorKeys);
    SwingUtilities.invokeLater(()->{if(timer!=null)timer.stop();if(layer!=null){if(panel!=null)layer.remove(panel);if(button!=null)layer.remove(button);layer.revalidate();layer.repaint();}panel=null;button=null;});
  }
}

package tv.moonga.classicworlds;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.*;
import net.runelite.api.SpritePixels;

/** The client's own glyph masks, offsets, advances and baseline, without TrueType substitution. */
final class ClientBitmapFont {
  static final class Glyph {
    final int width,height,x,y;
    final int[] mask;
    Glyph(int width,int height,int x,int y,int[] pixels){
      this.width=width;this.height=height;this.x=x;this.y=y;this.mask=pixels.clone();
    }
  }
  private final Glyph[] glyphs;
  private final int[] advances=new int[256];
  final int ascent;
  private final Map<Integer,BufferedImage[]> colours=new HashMap<>();
  ClientBitmapFont(byte[] metrics,Glyph[] glyphs){
    if(metrics==null||metrics.length!=257||glyphs==null||glyphs.length!=256)
      throw new IllegalArgumentException("Unsupported client bitmap font");
    for(int i=0;i<256;i++)advances[i]=metrics[i]&255;
    ascent=metrics[256]&255;this.glyphs=glyphs.clone();
  }
  static ClientBitmapFont from(byte[] metrics,SpritePixels[] sprites){
    if(metrics==null||sprites==null||sprites.length!=256)return null;
    Glyph[] glyphs=new Glyph[256];
    for(int i=0;i<256;i++){
      SpritePixels s=sprites[i];if(s==null)return null;
      glyphs[i]=new Glyph(s.getWidth(),s.getHeight(),s.getOffsetX(),s.getOffsetY(),s.getPixels());
    }
    return new ClientBitmapFont(metrics,glyphs);
  }
  int width(String text){int width=0;for(int i=0;i<text.length();i++)width+=advances[code(text.charAt(i))];return width;}
  void center(Graphics2D g,String text,int x,int baseline,int colour,int shadow){draw(g,text,x-width(text)/2,baseline,colour,shadow);}
  void draw(Graphics2D g,String text,int x,int baseline,int colour,int shadow){
    if(shadow>=0)draw(g,text,x+1,baseline+1,shadow,-1);
    BufferedImage[] images=colours.computeIfAbsent(colour,c->new BufferedImage[256]);
    for(int i=0;i<text.length();i++){
      int code=code(text.charAt(i));Glyph glyph=glyphs[code];
      if(code!=32&&glyph!=null&&glyph.width>0&&glyph.height>0){
        BufferedImage image=images[code];
        if(image==null){
          image=new BufferedImage(glyph.width,glyph.height,BufferedImage.TYPE_INT_ARGB);
          int[] pixels=new int[glyph.mask.length];for(int j=0;j<pixels.length;j++)if(glyph.mask[j]!=0)pixels[j]=0xff000000|(colour&0xffffff);
          image.setRGB(0,0,glyph.width,glyph.height,pixels,0,glyph.width);images[code]=image;
        }
        g.drawImage(image,x+glyph.x,baseline-ascent+glyph.y,null);
      }
      x+=advances[code];
    }
  }
  private static int code(char c){
    if(c==160)return 32;
    if(c>0&&c<128||c>=160&&c<=255)return c;
    String special="€\u0000‚ƒ„…†‡ˆ‰Š‹Œ\u0000Ž\u0000\u0000‘’“”•–—˜™š›œ\u0000žŸ";
    int at=special.indexOf(c);return at<0?63:128+at;
  }
}

