package tv.moonga.classicworlds;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.awt.geom.*;

/** Rasterise game-style text before Windows DPI scaling, then preserve its pixel edges. */
final class PixelDrawing {
  static Graphics2D raster(BufferedImage image){
    Graphics2D g=image.createGraphics();
    g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_OFF);
    g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
    g.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS,RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
    g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
    return g;
  }
  static void blit(Graphics graphics,BufferedImage image,int x,int y,int width,int height){
    Graphics2D g=(Graphics2D)graphics.create();
    try{
      g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
      g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_OFF);
      g.drawImage(image,x,y,width,height,null);
    }finally{g.dispose();}
  }
  /** Preserve the original DPI scale; enlargement is an explicit user preference. */
  static final class DeviceGrid {
    final AffineTransform transform;
    final double scale;
    DeviceGrid(Graphics graphics){this(graphics,DisplaySize.NORMAL);}
    DeviceGrid(Graphics graphics,DisplaySize size){
      transform=((Graphics2D)graphics).getTransform();
      scale=Math.hypot(transform.getScaleX(),transform.getShearY())*size.factor;
    }
    Point point(double x,double y){
      Point2D p=transform.transform(new Point2D.Double(x,y),null);
      return new Point((int)Math.round(p.getX()),(int)Math.round(p.getY()));
    }
    void draw(Graphics graphics,BufferedImage image,int deviceX,int deviceY){
      Graphics2D g=(Graphics2D)graphics.create();
      try{
        Shape clip=g.getClip();Shape deviceClip=clip==null?null:transform.createTransformedShape(clip);
        g.setTransform(new AffineTransform());if(deviceClip!=null)g.setClip(deviceClip);
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        g.drawImage(image,deviceX,deviceY,(int)Math.round(image.getWidth()*scale),(int)Math.round(image.getHeight()*scale),null);
      }finally{g.dispose();}
    }
    void centered(Graphics graphics,BufferedImage image,double x,double y){
      Point center=point(x,y);draw(graphics,image,center.x-(int)Math.round(image.getWidth()*scale)/2,center.y-(int)Math.round(image.getHeight()*scale)/2);
    }
  }
}

package tv.moonga.classicworlds;

import java.util.EnumSet;
import net.runelite.api.World;
import net.runelite.api.WorldType;

final class WorldEntry {
  final int id, players, location;
  final String activity, address;
  final EnumSet<WorldType> types;
  final int serverLocation;

  WorldEntry(int id, int players, int location, String activity, String address, EnumSet<WorldType> types) {
    this(id,players,location,activity,address,types,0);
  }
  WorldEntry(int id,int players,int location,String activity,String address,EnumSet<WorldType> types,int serverLocation) {
    this.id=id; this.players=players; this.location=location;
    this.activity=activity==null?"-":activity; this.address=address;
    this.types=types.clone();
    this.serverLocation=serverLocation;
  }
  WorldEntry withServerLocation(int value){return new WorldEntry(id,players,location,activity,address,types,value);}
  static WorldEntry from(World w) {
    return new WorldEntry(w.getId(),w.getPlayerCount(),w.getLocation(),w.getActivity(),w.getAddress(),w.getTypes());
  }
  boolean members() { return types.contains(WorldType.MEMBERS); }
  boolean selectable() { return players>=0 && players<=1980 && address!=null && !address.isBlank(); }
  String population() { return players<0?"OFF":players>1980?"FULL":Integer.toString(players); }
  String typeLabel() {
    if(types.contains(WorldType.DEADMAN))return "Deadman";
    if(types.contains(WorldType.HARDCORE_MAIN))return "Hardcore";
    if(types.contains(WorldType.PVP))return "PvP";
    if(types.contains(WorldType.HIGH_RISK))return "High Risk";
    if(types.contains(WorldType.BETA_WORLD))return "Beta";
    if(types.contains(WorldType.QUEST_SPEEDRUNNING))return "Speedrunning";
    if(types.contains(WorldType.SKILL_TOTAL))return "Skill total";
    return members()?"Members":"Free";
  }
  int background() {
    int base=0;
    if(types.contains(WorldType.HARDCORE_MAIN))base=16;
    else if(types.contains(WorldType.PVP))base=2;
    else if(types.contains(WorldType.DEADMAN))base=4;
    else if(types.contains(WorldType.BETA_WORLD))base=6;
    else if(types.contains(WorldType.SEASONAL))base=8;
    else if(types.contains(WorldType.HIGH_RISK))base=10;
    else if(types.contains(WorldType.QUEST_SPEEDRUNNING))base=12;
    return base+(members()?1:0);
  }
  String tooltip() {
    String risk=types.contains(WorldType.PVP)||types.contains(WorldType.HIGH_RISK)||types.contains(WorldType.DEADMAN)
        ?" — "+typeLabel():"";
    return (activity.equals("-")?typeLabel():activity)+risk;
  }
}

package tv.moonga.classicworlds;

import java.awt.*;
import java.util.function.BiConsumer;

/** Bitmap dropdowns share the selector's surface, avoiding heavyweight-canvas popup clipping. */
final class WorldMenus {
  private static final Rectangle[] BUTTONS={new Rectangle(8,27,175,23),new Rectangle(188,27,155,23),new Rectangle(348,27,183,23),new Rectangle(536,27,104,23),new Rectangle(645,27,112,23)};
  static final int DISMISS=-199;
  private final BiConsumer<String,Object> changed;
  private WorldPreferences options=WorldPreferences.DEFAULT;
  private DisplaySize textSize=DisplaySize.NORMAL;
  private int open=-1,keyboardRow=-1;
  private Point mouse=new Point(-1,-1);
  WorldMenus(BiConsumer<String,Object> changed){this.changed=changed;}
  void settings(WorldPreferences value,DisplaySize size){options=value;textSize=size;}
  boolean isOpen(){return open>=0;}
  boolean dismiss(){if(open<0)return false;open=-1;keyboardRow=-1;return true;}
  void mouse(Point point){mouse=point;keyboardRow=-1;}
  private Object[] values(){
    switch(open){case 0:return WorldPreferences.GameMode.values();case 1:return WorldPreferences.Region.values();case 2:return WorldPreferences.Membership.values();case 3:return new Boolean[]{true,false};default:return new Object[]{0,1,2,3,4};}
  }
  Rectangle menuBounds(){
    if(open<0)return new Rectangle();
    int width=Math.max(BUTTONS[open].width,open==4?190:180);
    return new Rectangle(Math.min(BUTTONS[open].x,765-width-4),52,width,values().length*20+2);
  }
  Integer hit(Point p){
    if(open>=0){Rectangle menu=menuBounds();if(menu.contains(p)){
      int row=(p.y-menu.y-1)/20;return row>=0&&row<values().length?-2000-row:DISMISS;
    }}
    for(int i=0;i<BUTTONS.length;i++)if(BUTTONS[i].contains(p))return -100-i;
    return open>=0?DISMISS:null;
  }
  boolean activate(int target){
    if(target==DISMISS){dismiss();return true;}
    if(target<=-100&&target>=-104){int next=-target-100;open=open==next?-1:next;keyboardRow=-1;return true;}
    if(target<=-2000&&target>=-2100&&open>=0){
      int row=-target-2000;Object[] values=values();if(row>=values.length)return true;
      int selectedMenu=open;Object value=values[row];dismiss();
      if(selectedMenu==0)changed.accept("preferredMode",value);
      else if(selectedMenu==1)changed.accept("preferredRegion",value);
      else if(selectedMenu==2)changed.accept("membership",value);
      else if(selectedMenu==3)changed.accept("compact",value);
      else if(row==0)changed.accept("showFlag",!options.showFlag);
      else if(row==1)changed.accept("buttonLine",options.buttonLine==WorldPreferences.ButtonLine.GAME_MODE?WorldPreferences.ButtonLine.CLICK_TO_SWITCH:WorldPreferences.ButtonLine.GAME_MODE);
      else changed.accept("displaySize",DisplaySize.values()[row-2]);
      return true;
    }
    return false;
  }
  void step(int direction){if(open>=0)keyboardRow=keyboardRow<0?(direction<0?values().length-1:0):Math.floorMod(keyboardRow+direction,values().length);}
  void choose(){if(open>=0&&keyboardRow>=0)activate(-2000-keyboardRow);}
  private String label(int row){
    if(open==3)return row==0?"Compact":"With activity";
    if(open==4){
      if(row==0)return "Country flag: "+(options.showFlag?"On":"Off");
      if(row==1)return "World info: "+(options.buttonLine==WorldPreferences.ButtonLine.GAME_MODE?"On":"Off");
      DisplaySize size=DisplaySize.values()[row-2];return (textSize==size?"(*) ":"( ) ")+"Hover text: "+size;
    }
    return values()[row].toString();
  }
  private boolean selected(int row){
    Object value=values()[row];
    switch(open){case 0:return value==options.mode;case 1:return value==options.region;case 2:return value==options.membership;case 3:return (Boolean)value==options.compact;default:return false;}
  }
  void paint(Graphics2D g,ClientBitmapFont font){
    g.setColor(new Color(0x171719));g.fillRect(0,23,765,32);
    String[] labels={"Mode: "+options.mode,"Region: "+options.region,"Membership: "+options.membership,"View: "+(options.compact?"Compact":"Activity"),"Options"};
    for(int i=0;i<BUTTONS.length;i++){
      Rectangle r=BUTTONS[i];g.setColor(new Color(open==i?0x48453a:0x303034));g.fillRect(r.x,r.y,r.width,r.height);
      g.setColor(new Color(0x857f68));g.drawRect(r.x,r.y,r.width-1,r.height-1);
      Shape clip=g.getClip();g.clipRect(r.x+5,r.y+2,r.width-22,r.height-4);
      if(font!=null)font.draw(g,labels[i],r.x+6,r.y+15,0xffffff,-1);g.setClip(clip);
      g.setColor(new Color(0xd7c580));g.fillPolygon(new int[]{r.x+r.width-15,r.x+r.width-7,r.x+r.width-11},new int[]{r.y+9,r.y+9,r.y+14},3);
    }
    if(open<0)return;
    Rectangle r=menuBounds();g.setColor(new Color(0x252527));g.fillRect(r.x,r.y,r.width,r.height);g.setColor(new Color(0xb1a078));g.drawRect(r.x,r.y,r.width-1,r.height-1);
    Integer target=hit(mouse);int hovered=keyboardRow>=0?keyboardRow:target!=null&&target<=-2000?-target-2000:-1;
    for(int row=0;row<values().length;row++){
      int y=r.y+1+row*20;if(row==hovered){g.setColor(new Color(0x514b36));g.fillRect(r.x+1,y,r.width-2,20);}
      if(font!=null)font.draw(g,label(row),r.x+7,y+14,selected(row)?0xffff00:0xffffff,-1);
    }
  }
}

package tv.moonga.classicworlds;

import java.util.*;
import net.runelite.api.WorldType;

/** Shared state for on-screen menus, persisted RuneLite settings and world ordering. */
public final class WorldPreferences {
  public enum GameMode {
    ALL("All modes"),MAIN_GAME("Main game"),PVP("Main game (PvP)"),HARDCORE("Hardcore"),DEADMAN("Deadman (Perm.)"),SPEEDRUNNING("Speedrunning");
    final String label;GameMode(String label){this.label=label;}@Override public String toString(){return label;}
    static GameMode of(EnumSet<WorldType> types){
      if(types.contains(WorldType.HARDCORE_MAIN))return HARDCORE;
      if(types.contains(WorldType.DEADMAN))return DEADMAN;
      if(types.contains(WorldType.QUEST_SPEEDRUNNING))return SPEEDRUNNING;
      return types.contains(WorldType.PVP)?PVP:MAIN_GAME;
    }
  }
  public enum Region {
    ALL("All regions",-1),USA("United States",0),USA_EAST("USA East",0),USA_WEST("USA West",0),UK("United Kingdom",1),AUSTRALIA("Australia",3),GERMANY("Germany",7),BRAZIL("Brazil",8),SINGAPORE("Singapore",10),SOUTH_AFRICA("South Africa",12),JAPAN("Japan",9),USA_EAST_WEST("USA East + West",0),USA_WEST_EAST("USA West + East",0);
    final String label;final int id;Region(String label,int id){this.label=label;this.id=id;}@Override public String toString(){return label;}
    int rank(WorldEntry world){
      if(this==ALL)return 0;
      // These WORLD_LOCATIONS values are also used by RuneLite's World Hopper.
      boolean east=world.location==0&&world.serverLocation==-42;
      boolean west=world.location==0&&world.serverLocation==-73;
      switch(this){
        case USA_EAST:return east?0:1;
        case USA_WEST:return west?0:1;
        case USA_EAST_WEST:return east?0:west?1:2;
        case USA_WEST_EAST:return west?0:east?1:2;
        default:return world.location==id?0:1;
      }
    }
  }
  public enum Membership {
    ALL("All worlds"),MEMBERS_ONLY("Members only"),F2P_ONLY("F2P only"),MEMBERS_FIRST("Members first"),F2P_FIRST("F2P first");
    final String label;Membership(String label){this.label=label;}@Override public String toString(){return label;}
  }
  public enum ButtonLine {
    CLICK_TO_SWITCH("Off"),GAME_MODE("On");
    final String label;ButtonLine(String label){this.label=label;}@Override public String toString(){return label;}
  }
  final GameMode mode;final Region region;final Membership membership;
  final boolean compact,showFlag;final ButtonLine buttonLine;
  static final WorldPreferences DEFAULT=new WorldPreferences(GameMode.ALL,Region.ALL,Membership.ALL,true,true,ButtonLine.CLICK_TO_SWITCH);
  WorldPreferences(GameMode mode,Region region,Membership membership,boolean compact,boolean showFlag,ButtonLine line){
    this.mode=mode==null?GameMode.ALL:mode;this.region=region==null?Region.ALL:region;this.membership=membership==null?Membership.ALL:membership;
    this.compact=compact;this.showFlag=showFlag;buttonLine=line==null?ButtonLine.CLICK_TO_SWITCH:line;
  }
  static WorldPreferences from(ClassicWorldSelectorConfig config){
    return config==null?DEFAULT:new WorldPreferences(config.preferredMode(),config.preferredRegion(),config.membership(),config.compact(),config.showFlag(),config.buttonLine());
  }
  WorldPreferences with(String key,Object value){
    return new WorldPreferences(key.equals("preferredMode")?(GameMode)value:mode,key.equals("preferredRegion")?(Region)value:region,
        key.equals("membership")?(Membership)value:membership,key.equals("compact")?(Boolean)value:compact,
        key.equals("showFlag")?(Boolean)value:showFlag,key.equals("buttonLine")?(ButtonLine)value:buttonLine);
  }
  List<WorldEntry> order(List<WorldEntry> source,Comparator<WorldEntry> base){
    List<WorldEntry> result=new ArrayList<>();
    for(WorldEntry world:source){
      if(membership==Membership.MEMBERS_ONLY&&!world.members())continue;
      if(membership==Membership.F2P_ONLY&&world.members())continue;
      result.add(world);
    }
    Comparator<WorldEntry> priority=Comparator.comparingInt((WorldEntry w)->mode==GameMode.ALL||GameMode.of(w.types)==mode?0:1)
        .thenComparingInt(region::rank)
        .thenComparingInt(w->membership==Membership.MEMBERS_FIRST&&!w.members()||membership==Membership.F2P_FIRST&&w.members()?1:0);
    result.sort(priority.thenComparing(base));return result;
  }
}

